<!-- File: pom.xml -->
<project xmlns="http://maven.apache.org/POM/4.0.0">
  <modelVersion>4.0.0</modelVersion>

  <groupId>com.bank</groupId>
  <artifactId>banking-common</artifactId>
  <!-- -SNAPSHOT = work in progress, can be re-published. A plain '1.0.0'
       would be an immutable RELEASE. -->
  <version>1.1.0-SNAPSHOT</version>
  <packaging>jar</packaging>

  <properties>
    <maven.compiler.release>21</maven.compiler.release>
  </properties>

  <dependencies>
    <dependency>
      <groupId>org.junit.jupiter</groupId>
      <artifactId>junit-jupiter</artifactId>
      <version>5.10.1</version>
      <scope>test</scope>
    </dependency>
  </dependencies>

  <!-- THIS tells `mvn deploy` WHERE to publish. Two targets:
       releases (immutable) and snapshots (re-publishable). -->
  <distributionManagement>
    <repository>
      <!-- id must match a <server> entry in settings.xml for credentials -->
      <id>nbi-releases</id>
      <name>NBI Release Repository</name>
      <url>https://nexus.nbi.internal/repository/maven-releases/</url>
    </repository>
    <snapshotRepository>
      <id>nbi-snapshots</id>
      <name>NBI Snapshot Repository</name>
      <url>https://nexus.nbi.internal/repository/maven-snapshots/</url>
    </snapshotRepository>
  </distributionManagement>
</project>
```

