package com.bank.common;

import java.math.BigDecimal;
import java.math.RoundingMode;

// Shared money utility used by EVERY National Bank of India microservice.
// This is the artifact that gets installed locally or deployed to Nexus.
public final class MoneyUtil {

    private MoneyUtil() { }

    // Always round money to 2 decimals, HALF_UP, never float/double.
    public static BigDecimal normalize(BigDecimal amount) {
        if (amount == null) {
            throw new IllegalArgumentException("amount required");
        }
        return amount.setScale(2, RoundingMode.HALF_UP);
    }

    // Compute simple interest for a loan: principal * rate% * years.
    public static BigDecimal simpleInterest(BigDecimal principal, BigDecimal ratePercent, int years) {
        BigDecimal rate = ratePercent.divide(new BigDecimal("100"));
        return normalize(principal.multiply(rate).multiply(new BigDecimal(years)));
    }
}
