package com.bank.common;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import static org.junit.jupiter.api.Assertions.*;

// These run in the 'test' phase. If they fail, nothing gets packaged,
// installed, or deployed — broken artifacts never reach the repository.
class MoneyUtilTest {

    @Test
    void normalizeRoundsToTwoDecimals() {
        assertEquals(new BigDecimal("1000.57"), MoneyUtil.normalize(new BigDecimal("1000.565")));
    }

    @Test
    void interestForRajeshLoan() {
        // Rajesh borrows 1,000,000 at 8% for 2 years -> 160000.00
        assertEquals(new BigDecimal("160000.00"),
                MoneyUtil.simpleInterest(new BigDecimal("1000000"), new BigDecimal("8"), 2));
    }
}
